def update_telemetry_data(telemetry_data, section, key):
    if key in telemetry_data[section]:
        telemetry_data[section][key] += 1
    else:
        telemetry_data[section][key] = 1


def populate_viz_and_event_handler_telemetry(definition, telemetry_data):
    visualizations = definition.get('visualizations', {})
    for viz_name in visualizations:
        viz = visualizations[viz_name]
        viz_type = viz.get('type')
        update_telemetry_data(telemetry_data, 'visualizations', viz_type)
        event_handlers = viz.get('eventHandlers', [])
        for event_handler in event_handlers:
            handlerType = event_handler.get('type')
            update_telemetry_data(telemetry_data, 'eventHandlers', handlerType)


def populate_telemetry_data_for_section(definition, telemetryData, section):
    sectionObject = definition.get(section, {})
    for elementName in sectionObject:
        element = sectionObject[elementName]
        elementType = element.get('type')
        update_telemetry_data(telemetryData, section, elementType)


def generate_telemetry_data(definition):
    telemetry_data = {
        'visualizations': {},
        'dataSources': {},
        'eventHandlers': {},
        'inputs': {}
    }

    populate_viz_and_event_handler_telemetry(definition, telemetry_data)
    populate_telemetry_data_for_section(
        definition, telemetry_data, 'dataSources')
    populate_telemetry_data_for_section(definition, telemetry_data, 'inputs')
    return telemetry_data
